#!/bin/sh\n\n# 1. Salin .env dari .env.example jika belum ada\nif [ ! -f .env ]; then\n    echo \"Creating .env file from .env.example...\"\n    cp .env.example .env\n    \n    # Otomatis sesuaikan isi .env lokal dengan konfigurasi database docker\n    sed -i 's/DB_CONNECTION=sqlite/DB_CONNECTION=mysql/g' .env\n    sed -i 's/# DB_HOST=127.0.0.1/DB_HOST=db/g' .env\n    sed -i 's/# DB_PORT=3306/DB_PORT=3306/g' .env\n    sed -i 's/# DB_DATABASE=laravel/DB_DATABASE=laravel/g' .env\n    sed -i 's/# DB_USERNAME=root/DB_USERNAME=laravel_user/g' .env\n    sed -i 's/# DB_PASSWORD=/DB_PASSWORD=laravel_password/g' .env\nfi\n\n# 2. Jalankan composer install jika vendor belum ada\nif [ ! -d vendor ]; then\n    echo \"Installing PHP dependencies (Composer)...\"\n    composer install --no-interaction --optimize-autoloader\nfi\n\n# 3. Generate APP_KEY jika belum ada\nif ! grep -q \"^APP_KEY=base64:\" .env; then\n    echo \"Generating Laravel Application Key...\"\n    php artisan key:generate --force\nfi\n\n# 4. Tunggu koneksi database siap (opsional tambahan jika docker-compose depends_on belum cukup)\necho \"Waiting for database connection to be ready...\"\nuntil php -r \"try { new PDO('mysql:host=db;port=3306;dbname=laravel', 'laravel_user', 'laravel_password'); exit(0); } catch (Exception \\\$e) { exit(1); }\"; do\n    echo \"Database not ready yet, retrying in 2 seconds...\"\n    sleep 2\ndone\n\n# 5. Jalankan migrasi database\necho \"Running database migrations...\"\nphp artisan migrate --force\n\n# 6. Berikan hak akses (permissions) yang benar untuk Apache\nchown -R www-data:www-data storage bootstrap/cache database/database.sqlite\nchmod -R 775 storage bootstrap/cache\n\n# 7. Jalankan Apache di foreground\necho \"Starting Apache Web Server...\"\nexec apache2-foreground\n